OUTRO = 'You heard Tae-ho burst late into the cast dinner and accidentally blurt out that the entire cast is being replaced. See you next time.'
CLOSING = ('seungchan', '안녕히 가세요!')

STORY = [('seungchan', '제가 지금 너무 급해서요.', 'I am in a huge rush right now.', [(860, '제가 지금 너무 급해서')], 'Adds polite -요 ending.'), ('seungchan', '여보세요? 선배님?', 'Hello? Senior?', [(861, '여보세요? 선배님?')], ''), ('taeho', '이거 진짜 말도 안 돼.', 'This really makes no sense at all.', [(871, '이거 진짜 말도 안 돼')], ''), ('taeho', '나 국장실 뒤집어 놓고 오느라고 늦었잖아.', "I'm late because I turned the director's office upside down before coming.", [(872, '나 국장실 뒤집어 놓고 오느라고 늦었잖아')], ''), ('joonmo', '왜 뒤집어 놔, 국장실을?', "Why turn the director's office upside down?", [(874, '왜 뒤집어 놔 국장실을')], ''), ('taeho', '우리 전원 하차라며?', "Didn't you say our whole cast is stepping down?", [(882, '우리 전원 하차라며')], ''), ('joonmo', '죄송합니다, 선생님.', 'I am deeply sorry, Teacher.', [(887, '죄송합니다 선생님')], ''), ('joonmo', '저희 저번 녹화가 마지막이었고요.', 'Our last recording was the final one.', [(888, '저희 저번 녹화가 마지막이었고요')], ''), ('joonmo', '멤버 체인지를 결정했습니다.', 'We decided on a cast change.', [(890, '멤버 체인지를 결정했습니다')], ''), ('taeho', '근데 왜 여정 선생님 모르셔?', "Then why doesn't Ms. Yuh-jung know?", [(892, '근데 왜 여정 선생님 모르셔?')], ''), ('taeho', '세상에, 말씀 안 드린 거야?', 'Good grief, did nobody tell her?', [(898, '세상에 말씀 안 드린 거야?')], ''), ('joonmo', '지금 어디라는 거야?', 'Where does he say he is right now?', [(899, '지금 어디라는 거야?')], '')]

WALK = [(0, None, "'I am in a huge rush right now.'"), (1, None, "'Hello? Senior?'"), (2, None, "'This really makes no sense at all.'"), (3, None, "'I'm late because I turned the director's office upside down before coming.'"), (4, None, "'Why turn the director's office upside down?'"), (5, None, "'Didn't you say our whole cast is stepping down?'"), (6, None, "'I am deeply sorry, Teacher.'"), (7, None, "'Our last recording was the final one.'"), (8, None, "'We decided on a cast change.'"), (9, None, "'Then why doesn't Ms. Yuh-jung know?'"), (10, None, "'Good grief, did nobody tell her?'"), (11, None, "'Where does he say he is right now?'")]
